function tuneNetworkRPS(){if(!IS_ROOT)return;try{let iface='';try{const r=fs.readFileSync('/proc/net/route','utf8').split('\n');for(const ln of r){const c=ln.split('\t');if(c.length>=8&&c[1]==='00000000'&&c[7]==='00000000'){iface=c[0];break;}}}catch(e){}if(!iface){try{const o=execFileSync('ip',['-o','-4','route','show','default'],{timeout:3000}).toString();const m=o.match(/dev\s+(\S+)/);if(m)iface=m[1];}catch(e){}}if(!iface){log.warn('NET','No se detecto interfaz por defecto para RPS');return;}const cores=HW_CORES>0?HW_CORES:2;const mask=((1<<Math.min(cores,32))-1).toString(16);let queues=[];try{queues=fs.readdirSync('/sys/class/net/'+iface+'/queues');}catch(e){queues=[];}let applied=0;for(const q of queues){if(/^rx-/.test(q)){try{fs.writeFileSync('/sys/class/net/'+iface+'/queues/'+q+'/rps_cpus',mask);applied++;}catch(e){}try{fs.writeFileSync('/sys/class/net/'+iface+'/queues/'+q+'/rps_flow_cnt','4096');}catch(e){}}}if(applied>0){try{fs.writeFileSync('/proc/sys/net/core/rps_sock_flow_entries','8192');}catch(e){}log.info('NET','RPS/RFS activado en '+iface+' ('+applied+' cola(s), mask='+mask+')');}else{log.warn('NET','No hay colas rx configurables en '+iface+' para RPS');}}catch(e){log.warn('NET','No se pudo ajustar RPS/RFS: '+e.message);}}
