let chatMessages=readJSON(CHAT_FILE,[]);if(!Array.isArray(chatMessages))chatMessages=[];const chatSockets=new Set();const CHAT_MAX=2000,CHAT_INITIAL=150;
function saveChat(){try{const tmp=CHAT_FILE+'.tmp';fs.writeFileSync(tmp,JSON.stringify(chatMessages));fs.renameSync(tmp,CHAT_FILE);}catch(e){log.err('CHAT','No se pudo guardar el chat: '+e.message);}}
function pushChat(msg){chatMessages.push(msg);while(chatMessages.length>CHAT_MAX)chatMessages.shift();saveChat();for(const ws of chatSockets)if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'msg',msg}));}
function applyReact(msgId,emoji,userId){const msg=chatMessages.find(m=>m.id===msgId);if(!msg)return null;if(!msg.reactions)msg.reactions={};if(!Array.isArray(msg.reactions[emoji]))msg.reactions[emoji]=[];const arr=msg.reactions[emoji];const i=arr.indexOf(userId);let active;if(i>=0){arr.splice(i,1);active=false;}else{arr.push(userId);active=true;}if(!arr.length)delete msg.reactions[emoji];saveChat();const payload={type:'react',msgId:msgId,emoji:emoji,userId:userId,active:active,count:arr.length};for(const ws of chatSockets)if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify(payload));return payload;}
function getPublicIPv4(){return new Promise((resolve)=>{const req=https.get('https://api.ipify.org',{timeout:5000},(res)=>{let data='';res.on('data',chunk=>data+=chunk);res.on('end',()=>{const ip=data.trim();if(/^\d+\.\d+\.\d+\.\d+$/.test(ip))resolve(ip);else resolve(null);});});req.on('error',()=>resolve(null));req.on('timeout',()=>{req.destroy();resolve(null);});req.setTimeout(5000);});}
