const SH={win:10000,allMax:240,apiMax:120,anonMax:45,pageMax:20,authMult:2.5,strikeMax:4,strikeWin:60000,connMax:100,blocks:[600000,3600000,21600000]};
const shBuckets=new Map(),shBlocked=new Map(),shStrikes=new Map(),shConns=new Map();
const shKey=ip=>ip.indexOf(':')>-1?(netKey(ip)||ip):ip;
function shHit(key,max){const n=Date.now();let e=shBuckets.get(key);if(!e||e.t<n){e={c:0,t:n+SH.win};shBuckets.set(key,e);}return ++e.c>max;}
function shStrike(k,ip){const n=Date.now();let e=shStrikes.get(k);if(!e||e.t<n)e={c:0,t:n+SH.strikeWin};e.c++;shStrikes.set(k,e);if(e.c<SH.strikeMax)return false;shStrikes.delete(k);const prev=shBlocked.get(k),lv=prev?Math.min(prev.lv+1,SH.blocks.length-1):0,dur=SH.blocks[lv];shBlocked.set(k,{until:n+dur,lv,ip,since:n});log.warn('SHIELD','IP bloqueada '+ip+' por '+Math.round(dur/60000)+' min (flood)');return true;}
function shTrackConn(sock){try{const ip=normIp(sock.remoteAddress);if(!ip||isProxyIp(ip))return;const k=shKey(ip),b=shBlocked.get(k);if(b&&b.until>Date.now())return void sock.destroy();const c=(shConns.get(k)||0)+1;shConns.set(k,c);sock.once('close',()=>{const x=(shConns.get(k)||1)-1;if(x<=0)shConns.delete(k);else shConns.set(k,x);});if(c>SH.connMax){sock.destroy();shStrike(k,ip);}}catch(e){}}
setInterval(()=>{const n=Date.now();for(const[k,e]of shBuckets)if(e.t<n)shBuckets.delete(k);for(const[k,e]of shStrikes)if(e.t<n)shStrikes.delete(k);for(const[k,b]of shBlocked)if(b.until+86400000<n)shBlocked.delete(k);if(shBuckets.size>300000)shBuckets.clear();},30000).unref();
app.use((req,res,next)=>{
  const ip=realIp(req);
  if(ip&&!isLocalIp(ip)){
    const k=shKey(ip),now=Date.now(),b=shBlocked.get(k);
    if(b&&b.until>now){if(!isProxyIp(normIp(req.socket.remoteAddress)))return req.socket.destroy();res.set({'Retry-After':String(Math.ceil((b.until-now)/1000)),Connection:'close'});return res.status(429).end();}
    const p=req.path,api=p.indexOf('/api/')===0,authed=!!getSession(ckGet(req,'panel_token')),m=authed?SH.authMult:1;
    let over=shHit('a:'+k,SH.allMax*m);
    if(api&&shHit('p:'+k,SH.apiMax*m))over=true;
    if(api&&!authed&&shHit('n:'+k,SH.anonMax))over=true;
    if(!api&&(p==='/'||p==='/index.html')&&shHit('h:'+k,SH.pageMax))over=true;
    if(over){shStrike(k,ip);res.set({'Retry-After':'10',Connection:'close'});return res.status(429).json({success:false,error:'Demasiadas solicitudes, espera unos segundos'});}
  }
  res.setHeader('X-Frame-Options','SAMEORIGIN');res.setHeader('Referrer-Policy','same-origin');if(req.secure||req.headers['x-forwarded-proto']==='https')res.setHeader('Strict-Transport-Security','max-age=31536000');
  next();});

