app.use((req,res,next)=>{const p=req.path;if(p.indexOf('/api/')!==0)return next();if(p==='/api/ban-status'||p==='/api/maintenance'||(p==='/api/login'&&req.method==='POST'))return next();const u=currentUser(req);if(u&&u.role==='admin'&&!u.banned)return next();const m=banMatch(req,u);if(!m)return next();banLearn(m,req);banHit(m);return res.status(403).json({success:false,banned:true,error:'Has sido baneado',ban:banPublicInfo(req,m)});});
app.get('/api/ban-status',async(req,res)=>{res.set('Cache-Control','no-store');try{const u=currentUser(req);if(u&&u.role==='admin'&&!u.banned)return res.json({success:true,banned:false});const m=banMatch(req,u);if(!m)return res.json({success:true,banned:false});banLearn(m,req);banHit(m);const info=banPublicInfo(req,m);const x=await banIspLookup(info.ip);if(x){info.isp=x.isp;info.org=x.org;info.as=x.as;info.proxy=x.proxy;info.hosting=x.hosting;info.mobile=x.mobile;if(x.cc){info.country=x.cc;info.region=x.region||info.region;info.city=x.city||info.city;info.timezone=x.tz||info.timezone;}}return res.json({success:true,banned:true,ban:info});}catch(e){return res.status(500).json({success:false});}});
