app.get('/api/bans/:id',requireAuth,requireAdmin,(req,res)=>{const b=bansDb.find(x=>x.id===req.params.id);if(!b)return res.status(404).json({success:false,error:'Baneo no encontrado'});const rel=getUsers().filter(u=>u.id!==b.userId&&u.role!=='admin'&&u.seen&&((u.seen.devices||[]).some(d=>(b.devices||[]).indexOf(d)>-1)||(u.seen.fps||[]).some(f=>(b.fps||[]).indexOf(f)>-1&&fpDistinct(f,b)))).map(u=>({id:u.id,username:u.username,banned:!!u.banned}));res.json({success:true,ban:Object.assign(banEntryOut(b),{devicesAll:(b.devices||[]).map(d=>d.slice(0,8)),related:rel})});});
