app.post('/api/users/:id/ban',requireAuth,requireAdmin,(req,res)=>{const us=getUsers();const t=us.find(x=>x.id===req.params.id);if(!t)return res.status(404).json({success:false,error:'Usuario no encontrado'});if(t.id===req.currentUser.id)return res.status(400).json({success:false,error:'No puedes banearte a ti mismo'});if(t.role==='admin')return res.status(400).json({success:false,error:'No puedes banear a un administrador (quítale primero el rol de admin)'});const reason=String((req.body&&req.body.reason)||'').trim().slice(0,200);const fp=banFingerprint(t);const g=fp.ips.map(i=>geoip.lookup(i)).find(Boolean)||{};bansDb=bansDb.filter(b=>b.userId!==t.id);const entry={id:'ban_'+Date.now()+'_'+crypto.randomBytes(3).toString('hex'),type:'user',userId:t.id,username:t.username,reason,createdAt:Date.now(),createdBy:req.currentUser.id,createdByName:req.currentUser.username,ips:fp.ips,devices:fp.devices,uas:fp.uas,nets:fp.nets,fps:fp.fps,emails:fp.emails,hits:0,country:g.country||null,region:g.region||null,city:g.city||null,timezone:g.timezone||null};bansDb.push(entry);saveBans();t.banned=true;t.banReason=reason;t.bannedAt=entry.createdAt;saveUsers(us);banKickUser(t.id);banEnrichEntry(entry);try{logActivity(req.currentUser.id,req.currentUser.username,'ban','Baneó a '+t.username+(reason?' ('+reason+')':''),null,{value:t.username});}catch(_e){}log.ok('AUTH','Baneo: '+t.username+' (por '+req.currentUser.username+')');res.json({success:true,ban:banEntryOut(entry)});});
app.post('/api/users/:id/unban',requireAuth,requireAdmin,(req,res)=>{const us=getUsers();const t=us.find(x=>x.id===req.params.id);const before=bansDb.length;bansDb=bansDb.filter(b=>b.userId!==req.params.id);if(!t&&bansDb.length===before)return res.status(404).json({success:false,error:'Ese usuario no está baneado'});if(t){t.banned=false;delete t.banReason;delete t.bannedAt;saveUsers(us);}saveBans();try{logActivity(req.currentUser.id,req.currentUser.username,'unban','Desbaneó a '+(t?t.username:req.params.id),null,{value:t?t.username:req.params.id});}catch(_e){}log.ok('AUTH','Desbaneo: '+(t?t.username:req.params.id)+' (por '+req.currentUser.username+')');res.json({success:true});});
app.delete('/api/bans/:id',requireAuth,requireAdmin,(req,res)=>{const b=bansDb.find(x=>x.id===req.params.id);if(!b)return res.status(404).json({success:false,error:'Baneo no encontrado'});bansDb=bansDb.filter(x=>x.id!==b.id);saveBans();if(b.userId&&!bansDb.some(x=>x.userId===b.userId)){const us=getUsers();const t=us.find(x=>x.id===b.userId);if(t&&t.banned){t.banned=false;delete t.banReason;delete t.bannedAt;saveUsers(us);}}try{logActivity(req.currentUser.id,req.currentUser.username,'unban','Quitó el baneo de '+(b.username||b.ips[0]||b.id),null,{value:b.username||b.ips[0]||b.id});}catch(_e){}log.ok('AUTH','Baneo eliminado: '+(b.username||b.ips[0]||b.id)+' (por '+req.currentUser.username+')');res.json({success:true});});
app.post('/api/bans/ip',requireAuth,requireAdmin,(req,res)=>{const ip=normIp((req.body&&req.body.ip)||'');if(!net.isIP(ip))return res.status(400).json({success:false,error:'IP inválida'});if(isLocalIp(ip))return res.status(400).json({success:false,error:'No se pueden banear IPs locales o privadas'});if(reqIps(req).indexOf(ip)>-1)return res.status(400).json({success:false,error:'No puedes banear tu propia IP'});if(bansDb.some(b=>b.type==='ip'&&Array.isArray(b.ips)&&b.ips[0]===ip))return res.status(400).json({success:false,error:'Esa IP ya está baneada'});const reason=String((req.body&&req.body.reason)||'').trim().slice(0,200);const g=geoip.lookup(ip)||{};const entry={id:'ban_'+Date.now()+'_'+crypto.randomBytes(3).toString('hex'),type:'ip',userId:null,username:null,reason,createdAt:Date.now(),createdBy:req.currentUser.id,createdByName:req.currentUser.username,ips:[ip],devices:[],uas:[],nets:[],country:g.country||null,region:g.region||null,city:g.city||null,timezone:g.timezone||null};bansDb.push(entry);saveBans();banEnrichEntry(entry);try{logActivity(req.currentUser.id,req.currentUser.username,'ban','Baneó la IP '+ip+(reason?' ('+reason+')':''),null,{value:ip});}catch(_e){}log.ok('AUTH','Baneo de IP: '+ip+' (por '+req.currentUser.username+')');res.json({success:true,ban:banEntryOut(entry)});});

app.post('/api/register',async(req,res)=>{if(maintDb.enabled)return res.status(503).json({success:false,maintenance:true,message:maintDb.message||'',error:'Panel en mantenimiento'});{const _g=await regGuard(req).catch(()=>null);if(_g)return res.status(_g.banned?403:429).json(_g);}const{username,password,confirmPassword,email}=req.body||{};const cu=(username||'').trim();const ce=(email||'').trim();if(!cu||!password||!confirmPassword)return res.status(400).json({success:false,error:'Completa todos los campos'});if(!/^[a-zA-Z0-9_]{3,20}$/.test(cu))return res.status(400).json({success:false,error:'Usuario inválido (3-20 caracteres, letras/números/_)'});if(password.length<6)return res.status(400).json({success:false,error:'La contraseña debe tener al menos 6 caracteres'});if(password!==confirmPassword)return res.status(400).json({success:false,error:'Las contraseñas no coinciden'});if(ce&&!EMAIL_RE.test(ce))return res.status(400).json({success:false,error:'Correo inválido'});const us=getUsers();if(findUser(us,cu))return res.status(400).json({success:false,error:'El usuario ya existe'});if(ce&&findUserByEmail(us,ce))return res.status(400).json({success:false,error:'Ese correo ya está en uso'});const role=us.length===0?'admin':'user';const u=makeUser(cu,password,role,ce||null);us.push(u);saveUsers(us);log.ok('AUTH','Registro: '+cu+' ('+role+')');try{logActivity(u.id,u.username,'register','Se registró en el panel ('+role+')',null,{value:role});}catch(_e){}const t=createSession(u.id);res.cookie('panel_token',t,{httpOnly:true,maxAge:SESSION_TTL,sameSite:'lax',secure:req.secure||(req.headers['x-forwarded-proto']==='https')});const ip0=req.clientIp||req.headers['x-forwarded-for']?.split(',')[0]?.trim()||req.socket.remoteAddress;const geo0=geoip.lookup(ip0);logSession(u.id,u.username,ip0,req.userAgent,geo0?.country||'Unknown',{device:getDevId(req),sip:realIp(req)});banSeenTouch(us,u,req);res.json({success:true,user:publicUser(u)});});
app.post('/api/login',(req,res)=>{const{username,password}=req.body||{};if(!username||!password)return res.status(400).json({success:false,error:'Usuario y contraseña requeridos'});const us=getUsers();const u=findUser(us,username);if(!u||!verifyPassword(password,u.salt,u.hash))return res.status(401).json({success:false,error:'Credenciales inválidas'});if(u.role!=='admin'){const _bm=banMatch(req,u.banned?u:null);if(_bm){banLearn(_bm,req);banHit(_bm);}if(_bm)return res.status(403).json({success:false,banned:true,error:'Has sido baneado',ban:banPublicInfo(req,_bm)});}if(maintDb.enabled&&u.role!=='admin')return res.status(503).json({success:false,maintenance:true,message:maintDb.message||'',error:'Panel en mantenimiento'});const t=createSession(u.id);res.cookie('panel_token',t,{httpOnly:true,maxAge:SESSION_TTL,sameSite:'lax',secure:req.secure||(req.headers['x-forwarded-proto']==='https')});log.ok('AUTH','Login: '+username);const ip=req.clientIp||req.headers['x-forwarded-for']?.split(',')[0]?.trim()||req.socket.remoteAddress;const geo=geoip.lookup(ip);const country=geo?.country||'Unknown';logSession(u.id,u.username,ip,req.userAgent,country,{device:getDevId(req),sip:realIp(req)});banSeenTouch(us,u,req);logActivity(u.id,u.username,'login','Inicio de sesión desde '+country);res.json({success:true,user:publicUser(u)});});
app.post('/api/logout',(req,res)=>{const t=req.cookies&&req.cookies.panel_token;if(t&&typeof t==='string'){sessions.delete(tokHash(t));persistSessionsDebounced();}res.clearCookie('panel_token');res.json({success:true});});
app.post('/api/logout-all',requireAuth,(req,res)=>{const uid=req.currentUser.id;const currentToken=req.cookies&&req.cookies.panel_token;let count=0;for(const[t,s]of sessions){if(s.userId===uid){sessions.delete(t);count++;}}persistSessionsDebounced();res.clearCookie('panel_token');log.info('AUTH',req.currentUser.username+' cerró '+count+' sesión(es) propia(s)');res.json({success:true,count});});
app.post('/api/forgot-password',async(req,res)=>{const{identifier}=req.body||{};const id=String(identifier||'').trim();if(!id)return res.status(400).json({success:false,error:'Escribe tu usuario o correo'});const us=getUsers();const u=findUser(us,id)||findUserByEmail(us,id);if(u&&u.email){const token=createResetToken(u.id);const link=mailer.buildPanelLink(req,'?reset='+token);const lang=VALID_LANGS.includes(u.language)?u.language:'es';const{subject,html}=mailer.buildResetPasswordEmail(lang,u.username,link);mailer.sendMail(u.email,subject,html,log).catch(()=>{});log.info('AUTH','Solicitud de restablecimiento de contraseña para '+u.username);}res.json({success:true});});
app.get('/api/reset-password/:token',(req,res)=>{const r=getResetToken(req.params.token);if(!r)return res.status(400).json({success:false,error:'Enlace inválido o expirado'});res.json({success:true});});
app.post('/api/reset-password',(req,res)=>{const{token,newPassword}=req.body||{};if(!token)return res.status(400).json({success:false,error:'Falta el token'});if(!newPassword||newPassword.length<6)return res.status(400).json({success:false,error:'La nueva contraseña debe tener al menos 6 caracteres'});const r=getResetToken(token);if(!r)return res.status(400).json({success:false,error:'Enlace inválido o expirado'});const us=getUsers();const u=us.find(x=>x.id===r.userId);if(!u){consumeResetToken(token);return res.status(400).json({success:false,error:'Usuario no encontrado'});}u.salt=crypto.randomBytes(16).toString('hex');u.hash=hashPassword(newPassword,u.salt);u.updatedAt=Date.now();saveUsers(us);consumeResetToken(token);for(const[t,s]of sessions)if(s.userId===u.id)sessions.delete(t);persistSessionsDebounced();log.ok('AUTH','Contraseña restablecida vía email para '+u.username);const t2=createSession(u.id);res.cookie('panel_token',t2,{httpOnly:true,maxAge:SESSION_TTL,sameSite:'lax',secure:req.secure||(req.headers['x-forwarded-proto']==='https')});const ip=req.clientIp||req.headers['x-forwarded-for']?.split(',')[0]?.trim()||req.socket.remoteAddress;const geo=geoip.lookup(ip);const country=geo?.country||'Unknown';logSession(u.id,u.username,ip,req.userAgent,country);logActivity(u.id,u.username,'login','Restableció su contraseña por email e inició sesión desde '+country);res.json({success:true,user:publicUser(u)});});
