app.post('/api/change-password',requireAuth,(req,res)=>{const{oldPassword,newPassword}=req.body||{};if(!newPassword||newPassword.length<6)return res.status(400).json({success:false,error:'La nueva contraseña debe tener al menos 6 caracteres'});if(!verifyPassword(oldPassword||'',req.currentUser.salt,req.currentUser.hash))return res.status(401).json({success:false,error:'Contraseña actual incorrecta'});const us=getUsers();const u=us.find(x=>x.id===req.currentUser.id);u.salt=crypto.randomBytes(16).toString('hex');u.hash=hashPassword(newPassword,u.salt);u.updatedAt=Date.now();saveUsers(us);res.json({success:true});});
const uploadAvatar=multer({storage:multer.memoryStorage(),limits:{fileSize:2*1024*1024},fileFilter:(req,file,cb)=>cb(null,/^image\/(png|jpe?g|gif|webp)$/i.test(file.mimetype))});
