const uploadChatFiles=multer({storage:multer.diskStorage({destination:(req,file,cb)=>cb(null,CHAT_FILES_DIR),filename:(req,file,cb)=>{const safe=String(file.originalname||'file').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,120);cb(null,Date.now()+'_'+crypto.randomBytes(3).toString('hex')+'_'+safe);}}),limits:{fileSize:25*1024*1024}});
