function removeBackgrounds(id){try{for(const f of fs.readdirSync(BACKGROUNDS_DIR))if(f.startsWith(id+'.'))fs.unlinkSync(path.join(BACKGROUNDS_DIR,f));}catch(e){}}
app.post('/api/profile',requireAuth,(req,res)=>{const{username,bio,language,email}=req.body||{};const us=getUsers();const u=us.find(x=>x.id===req.currentUser.id);if(!u)return res.status(404).json({success:false,error:'Usuario no encontrado'});if(typeof username==='string'){const cu=username.trim();if(!/^[a-zA-Z0-9_]{3,20}$/.test(cu))return res.status(400).json({success:false,error:'Usuario inválido'});if(cu.toLowerCase()!==u.username.toLowerCase()&&findUser(us,cu))return res.status(400).json({success:false,error:'El usuario ya existe'});u.username=cu;}if(typeof bio==='string')u.bio=bio.slice(0,200);if(typeof language==='string'&&VALID_LANGS.includes(language))u.language=language;if(typeof email==='string'){const ce=email.trim();if(!ce){u.email=null;}else{if(!EMAIL_RE.test(ce))return res.status(400).json({success:false,error:'Correo inválido'});const other=findUserByEmail(us,ce);if(other&&other.id!==u.id)return res.status(400).json({success:false,error:'Ese correo ya está en uso'});u.email=ce.toLowerCase();}}u.updatedAt=Date.now();saveUsers(us);res.json({success:true,user:publicUser(u)});});
app.put('/api/profile/pins',requireAuth,(req,res)=>{const raw=req.body&&req.body.pins;if(!Array.isArray(raw))return res.status(400).json({success:false,error:'Lista de fijados inválida'});const clean=[];for(const x of raw){if(typeof x==='string'&&/^server_[0-9]+$/.test(x)&&clean.indexOf(x)<0)clean.push(x);if(clean.length>=500)break;}const us=getUsers();const u=us.find(x=>x.id===req.currentUser.id);if(!u)return res.status(404).json({success:false,error:'Usuario no encontrado'});u.pins=clean;saveUsers(us);res.json({success:true,pins:clean});});
app.post('/api/profile/avatar',requireAuth,uploadAvatar.single('avatar'),(req,res)=>{if(!req.file)return res.status(400).json({success:false,error:'Imagen inválida (PNG/JPG/GIF/WEBP, max 2MB)'});const us=getUsers();const u=us.find(x=>x.id===req.currentUser.id);if(!u)return res.status(404).json({success:false,error:'Usuario no encontrado'});removeAvatars(u.id);const ext=MIME_EXT[req.file.mimetype]||'png';fs.writeFileSync(path.join(AVATARS_DIR,u.id+'.'+ext),req.file.buffer);u.avatarExt=ext;u.updatedAt=Date.now();saveUsers(us);res.json({success:true,user:publicUser(u)});});
app.delete('/api/profile/avatar',requireAuth,(req,res)=>{const us=getUsers();const u=us.find(x=>x.id===req.currentUser.id);removeAvatars(u.id);u.avatarExt=null;u.updatedAt=Date.now();saveUsers(us);res.json({success:true,user:publicUser(u)});});
