if(type==='bedrock'){const[raw,numericIp]=await Promise.all([bedrockPing(host,port,4500),numericIpP]);const p=bedrockParse(raw.str);const editionMap={MCPE:'Bedrock (MCPE)',MCEE:'Bedrock Education'};const geo=numericIp?geoip.lookup(numericIp):null;const lines=[p.motd1,p.motd2].filter(Boolean);return{ok:true,data:{online:true,ip:origHost,numericIp:numericIp||(mcIsIPv4(host)?host:null),port,srv:null,hostname:address,edition:p.edition||null,version:p.versionName,protocol:p.protocol?parseInt(p.protocol,10):null,software:editionMap[p.edition]||(p.gamemode?('Bedrock · '+p.gamemode):'Bedrock'),gamemode:p.gamemode||null,gamemodeNumeric:(p.gamemodeNumeric!==''&&p.gamemodeNumeric!=null)?p.gamemodeNumeric:null,levelName:mcStripColors(p.motd2)||null,serverGuid:p.serverGuid||null,ipv6Port:p.portV6||null,nintendoLimited:p.nintendo!==''?p.nintendo==='1':null,geo:mcGeoOut(geo),motd:{raw:lines,clean:lines.map(mcStripColors),runs:lines.map(l=>mcMotdRuns(l)[0]||[])},players:{online:p.online,max:p.max,list:[],source:null},debug:{pingMs:raw.pingMs}}};}
// Java: Server List Ping y Query (UDP) en paralelo para no sumar esperas
const queryP=mcFullQuery(host,port,1500).catch(()=>null);
const[res,numericIp]=await Promise.all([javaPing(host,port,4500),numericIpP]);const q=await Promise.race([queryP,new Promise(r=>setTimeout(()=>r(null),Math.min(1500,Math.max(700,(res.tcpMs||100)*5))))]);const json=res.json||{};
const motdRaw=mcFlattenChat(json.description);const rawLines=motdRaw.split('\n');const cleanLines=rawLines.map(mcStripColors).filter(l=>l.length);const runs=mcMotdRuns(json.description);
const sample=json.players&&Array.isArray(json.players.sample)?json.players.sample.filter(s=>s&&s.name):[];const uuidByName={};for(const s of sample)uuidByName[mcStripColors(s.name).toLowerCase()]=s.id||null;
const qPlayers=q&&q.players.length?q.players:null;const list=qPlayers?qPlayers.map(n=>({name:n,uuid:uuidByName[String(n).toLowerCase()]||null})):sample.map(s=>({name:mcStripColors(s.name),uuid:s.id||null}));
const modNames=(json.forgeData&&Array.isArray(json.forgeData.mods))?json.forgeData.mods.map(m=>m.modId||m.modid).filter(Boolean):(json.modinfo&&Array.isArray(json.modinfo.modList))?json.modinfo.modList.map(m=>m.modid+(m.version?(' '+m.version):'')):null;
