function slClean(b,old){b=b||{};const o=old||{};const name=String(b.name!=null?b.name:o.name||'').trim().slice(0,48);const address=String(b.address!=null?b.address:o.address||'').trim();const type=['java','bedrock','auto'].includes(b.type)?b.type:(o.type||'auto');const description=String(b.description!=null?b.description:o.description||'').trim().slice(0,140);if(!name)return{error:'Falta el nombre'};if(!address||address.length>255||!SL_ADDR_RE.test(address))return{error:'Dirección inválida (usa IP o dominio, con puerto opcional ip:puerto)'};return{v:{name,address,type,description}};}
