if(!target||target.toLowerCase()==='self')target=SERVER_IP||'';
if(!target||target.length>253)return res.status(400).json({success:false,error:'Indica una IP o un dominio válido'});
const isIp=isValidIpv4(target)||(target.indexOf(':')!==-1&&LOOKUP_IPV6_RE.test(target));
if(!isIp&&!LOOKUP_HOST_RE.test(target))return res.status(400).json({success:false,error:'Formato inválido. Usa una IP (ej: 1.1.1.1) o un dominio (ej: ejemplo.com)'});
