function chmodTreeExecMode(p,m){try{const st=fs.statSync(p);if(st.isFile()){fs.chmodSync(p,m);return;}if(st.isDirectory()){fs.chmodSync(p,m);for(const e of fs.readdirSync(p,{withFileTypes:true}))chmodTreeExecMode(path.join(p,e.name),m);}}catch(e){}}
