app.post('/api/servers/:id/files/move',requireAuth,guard('files'),(req,res)=>{const{items,dest}=req.body||{};if(!Array.isArray(items)||!items.length)return res.status(400).json({success:false,error:'Nada que mover'});const base=path.join(SERVERS_PATH,req.params.id);const baseAbs=path.resolve(base);let dstDir;try{dstDir=safeJoin(base,(dest&&dest!=='.')?String(dest):'.');if(!fs.existsSync(dstDir))return res.status(400).json({success:false,error:'La carpeta destino no existe'});if(!fs.statSync(dstDir).isDirectory())return res.status(400).json({success:false,error:'El destino no es una carpeta'});}catch(e){return res.status(400).json({success:false,error:'Carpeta destino inválida'});}const moved=[],skipped=[];for(const it of items){const rel=String(it||'').replace(/\\/g,'/').replace(/^\/+/,'');if(!rel||rel==='.')continue;let src;try{src=safeJoin(base,rel);}catch(e){skipped.push({name:rel,reason:'Ruta inválida'});continue;}if(src===baseAbs)continue;const name=path.basename(src);if(!fs.existsSync(src)){skipped.push({name,reason:'No existe'});continue;}const dst=path.join(dstDir,name);if(src===dst||path.dirname(src)===dstDir){skipped.push({name,reason:'Ya está en esa carpeta'});continue;}if(dstDir===src||dstDir.startsWith(src+path.sep)){skipped.push({name,reason:'No se puede mover una carpeta dentro de sí misma'});continue;}if(fs.existsSync(dst)){skipped.push({name,reason:'Ya existe un elemento con ese nombre en el destino'});continue;}try{try{fs.renameSync(src,dst);}catch(e1){if(e1.code!=='EXDEV')throw e1;fs.cpSync(src,dst,{recursive:true});fs.rmSync(src,{recursive:true,force:true});}moved.push(name);}catch(e){skipped.push({name,reason:e.code==='EACCES'||e.code==='EPERM'?'Sin permisos':e.message});}}if(moved.length)log.ok('FILES','Movidos '+moved.length+' elemento(s) en '+req.params.id+' -> /'+(dest&&dest!=='.'?dest:'')+' por '+req.currentUser.username);if(!moved.length&&skipped.length)return res.status(400).json({success:false,error:skipped[0].reason,moved,skipped});res.json({success:true,moved,skipped});});
const ARCH_EXT_RE=/\.(tar\.gz|tar\.bz2|tar\.xz|tar\.zst|tgz|tbz2|tbz|txz|tzst|zip|rar|7z|tar|gz|bz2|xz|zst)$/i;
function runTool(cmd,args){return new Promise(rs=>execFile(cmd,args,{timeout:300000,maxBuffer:8*1024*1024},(e,so,se)=>rs({cmd,missing:!!(e&&e.code==='ENOENT'),ok:!e,err:e?String((se||e.message||'')).split('\n').filter(Boolean).slice(-1)[0]||'error':''})));}
async function runChain(chain){let lastErr=null,tools=[];for(const [cmd,args] of chain){const r=await runTool(cmd,args);tools.push(cmd);if(r.ok)return{ok:true};if(!r.missing)lastErr=r.err;}if(lastErr)return{ok:false,bad:true,err:lastErr};return{ok:false,missing:true,tools};}
function decompressSingle(tool,args,archive,outFile){return new Promise(rs=>{const cp=require('child_process').spawn(tool,args.concat([archive]));const ws=fs.createWriteStream(outFile);let err='',done=false;const fin=r=>{if(!done){done=true;rs(r);}};cp.stdout.pipe(ws);cp.stderr.on('data',d=>{err+=d;});cp.on('error',e=>{try{ws.destroy();}catch(_){}fin({ok:false,missing:e.code==='ENOENT',err:e.message});});cp.on('close',c=>{ws.end(()=>fin(c===0?{ok:true}:{ok:false,err:String(err).split('\n').filter(Boolean).slice(-1)[0]||'error'}));});});}
app.post('/api/servers/:id/files/extract',requireAuth,guard('files'),diskGuard,(req,res)=>{const{path:rel}=req.body||{};if(!rel||typeof rel!=='string'||!ARCH_EXT_RE.test(rel))return res.status(400).json({success:false,code:'BAD_FORMAT',error:'Formato no soportado'});let tmpDir=null;try{const base=path.join(SERVERS_PATH,req.params.id);const archive=safeJoin(base,rel);if(!fs.existsSync(archive))return res.status(404).json({success:false,error:'Archivo no encontrado'});const finalTarget=safeJoin(base,path.dirname(rel));fs.mkdirSync(finalTarget,{recursive:true});tmpDir=path.join(base,'.extract_'+crypto.randomBytes(6).toString('hex'));fs.mkdirSync(tmpDir,{recursive:true});const T=tmpDir;const bn=path.basename(archive);const ext=bn.match(ARCH_EXT_RE)[1].toLowerCase();
(async()=>{try{let r;
if(ext==='zip')r=await runChain([['unzip',['-o','-q',archive,'-d',T]],['7z',['x',archive,'-o'+T,'-y']],['7zz',['x',archive,'-o'+T,'-y']],['7za',['x',archive,'-o'+T,'-y']],['bsdtar',['-xf',archive,'-C',T]]]);
else if(ext==='rar')r=await runChain([['unrar',['x','-o+','-idq',archive,T+'/']],['7z',['x',archive,'-o'+T,'-y']],['7zz',['x',archive,'-o'+T,'-y']],['7za',['x',archive,'-o'+T,'-y']],['bsdtar',['-xf',archive,'-C',T]]]);
else if(ext==='7z')r=await runChain([['7z',['x',archive,'-o'+T,'-y']],['7zz',['x',archive,'-o'+T,'-y']],['7za',['x',archive,'-o'+T,'-y']],['bsdtar',['-xf',archive,'-C',T]]]);
else if(['tar','tar.gz','tgz','tar.bz2','tbz2','tbz','tar.xz','txz','tar.zst','tzst'].includes(ext)){const fl=(ext==='tar')?['-xf']:(ext==='tar.gz'||ext==='tgz')?['-xzf']:(ext==='tar.bz2'||ext==='tbz2'||ext==='tbz')?['-xjf']:(ext==='tar.xz'||ext==='txz')?['-xJf']:['--zstd','-xf'];r=await runChain([['tar',fl.concat([archive,'-C',T,'--no-same-owner'])],['bsdtar',['-xf',archive,'-C',T]]]);}
else{const outName=bn.replace(/\.(gz|bz2|xz|zst)$/i,'')||('out_'+Date.now());const out=path.join(T,outName);const tool=ext==='gz'?'gzip':ext==='bz2'?'bzip2':ext==='xz'?'xz':'zstd';const args=['-dc'];r=await decompressSingle(tool,args,archive,out);if(r.missing)r={ok:false,missing:true,tools:[tool]};else if(!r.ok)r={ok:false,bad:true,err:r.err};}
if(!r.ok){try{fs.rmSync(tmpDir,{recursive:true,force:true});}catch(_e){}if(r.missing)return res.status(500).json({success:false,code:'MISSING_TOOL',tool:(r.tools||[])[0]==='unzip'||ext==='rar'?(ext==='rar'?'unrar / p7zip-full':'unzip / p7zip-full'):(r.tools||[]).join(' / '),error:'Falta instalar la herramienta para descomprimir'});return res.status(500).json({success:false,code:'BAD_ARCHIVE',error:'No se pudo extraer: '+(r.err||'archivo dañado')});}
stripSymlinks(tmpDir);copyTreeSafe(tmpDir,finalTarget,base);try{fs.rmSync(tmpDir,{recursive:true,force:true});}catch(_e){}
try{logActivity(req.currentUser.id,req.currentUser.username,'file_extract','Extrajo un archivo comprimido',req.params.id,{file:String(rel).slice(0,200)});}catch(_e){}
res.json({success:true,folder:path.dirname(rel)});}catch(e){try{fs.rmSync(tmpDir,{recursive:true,force:true});}catch(_e){}res.status(500).json({success:false,code:'BAD_ARCHIVE',error:'No se pudo extraer'});}})();}catch(e){if(tmpDir){try{fs.rmSync(tmpDir,{recursive:true,force:true});}catch(_e){}}res.status(400).json({success:false,error:e.message});}});
app.post('/api/servers/:id/files/archive',requireAuth,guard('files'),diskGuard,(req,res)=>{const{items,folder,name}=req.body||{};if(!Array.isArray(items)||!items.length)return res.status(400).json({success:false,error:'Nada que comprimir'});let nm=String(name||'').trim();if(!/\.zip$/i.test(nm))nm+='.zip';if(!/^[A-Za-z0-9._-]+\.zip$/.test(nm))return res.status(400).json({success:false,error:'Nombre de archivo inválido'});const serverDir=path.join(SERVERS_PATH,req.params.id);let baseDir;try{baseDir=safeJoin(serverDir,(folder&&folder!=='.'?folder:'.'));}catch(e){return res.status(400).json({success:false,error:'Carpeta actual inválida'});}const rels=[];for(const it of items){const relS=String(it||'').replace(/\\/g,'/').replace(/^\/+/,'');if(!relS||relS==='.'||relS==='..')continue;let abs;try{abs=safeJoin(serverDir,relS);}catch(e){continue;}if(!fs.existsSync(abs))continue;const relBase=path.relative(baseDir,abs);if(!relBase||relBase.startsWith('..')||path.isAbsolute(relBase))continue;if(relBase===nm)continue;rels.push(relBase);}if(!rels.length)return res.status(400).json({success:false,error:'Ningún elemento válido para comprimir'});const args=['-r','-y','-q',nm].concat(rels);execFile('zip',args,{cwd:baseDir,timeout:300000},(err)=>{if(err){return res.status(500).json({success:false,error:'No se pudo crear el .zip (instala zip en el VPS)'});}res.json({success:true,file:nm});});});
// Empaquetador .phar en Node puro (no necesita PHP en el VPS)
function pharCrc32(buf){let c,crc=0xFFFFFFFF;const T=pharCrc32.T||(pharCrc32.T=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){c=n;for(let k=0;k<8;k++)c=c&1?(0xEDB88320^(c>>>1)):(c>>>1);t[n]=c>>>0;}return t;})());for(let i=0;i<buf.length;i++)crc=T[(crc^buf[i])&0xFF]^(crc>>>8);return(crc^0xFFFFFFFF)>>>0;}
function pharSerialize(v){if(v===null||v===undefined)return'N;';if(typeof v==='boolean')return'b:'+(v?1:0)+';';if(typeof v==='number')return Number.isInteger(v)?'i:'+v+';':'d:'+v+';';if(Array.isArray(v)){let o='a:'+v.length+':{';v.forEach((x,i)=>{o+='i:'+i+';'+pharSerialize(x);});return o+'}';}if(typeof v==='object'){const ks=Object.keys(v);let o='a:'+ks.length+':{';for(const k of ks)o+=pharSerialize(String(k))+pharSerialize(v[k]);return o+'}';}const s=String(v);return's:'+Buffer.byteLength(s,'utf8')+':"'+s+'";';}
function pharBuild(rootDir,outFile,kind,meta,entry,label){
const zlib=require('zlib');
const base=path.resolve(rootDir);const files=[];
(function walk(dir,rel){let ents;try{ents=fs.readdirSync(dir,{withFileTypes:true});}catch(e){return;}ents.sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:0);for(const en of ents){const n=en.name;if(n[0]==='.'||n==='__MACOSX'||n==='Thumbs.db'||n==='desktop.ini')continue;if(en.isSymbolicLink())continue;const full=path.join(dir,n),r=rel?rel+'/'+n:n;if(en.isDirectory())walk(full,r);else if(en.isFile())files.push({full,rel:r});}})(base,'');
if(!files.length)return{err:'EMPTY'};
const esc=s=>String(s==null?'':s).replace(/[\\"$]/g,m=>'\\'+m);
meta=(meta&&typeof meta==='object')?Object.assign({},meta):{};
const now=Math.floor(Date.now()/1000);let stub,metadata;
if(kind==='plugin'){const name=meta.name!=null?String(meta.name):label,version=meta.version!=null?String(meta.version):'1.0.0';meta.creationDate=now;metadata=meta;
stub='<?php echo "PocketMine-MP plugin '+esc(name)+' v'+esc(version)+'\\nThis file has been generated using Kynex Panel at '+new Date().toUTCString()+'\\n----------------\\n"; if(extension_loaded("phar")){$phar = new \\Phar(__FILE__); foreach($phar->getMetadata() as $key => $value){ echo ucfirst($key).": ".(is_array($value) ? implode(", ", $value) : $value)."\\n"; }} __HALT_COMPILER();';}
else if(kind==='api'){metadata={name:meta.name!=null?meta.name:label,version:meta.version!=null?meta.version:'1.0.0',creationDate:now};
stub='<?php define("pocketmine\\\\PATH", "phar://". __FILE__ ."/"); require_once("phar://". __FILE__ ."/src/pocketmine/PocketMine.php");  __HALT_COMPILER();';}
else{metadata={name:label,creationDate:now};stub=entry?'<?php require("phar://". __FILE__ ."/'+esc(entry)+'"); __HALT_COMPILER();':'<?php __HALT_COMPILER();';}
// pasada 1: tamaño, crc32 y compresión
let anyGz=false;const items=[];
for(const f of files){const st=fs.statSync(f.full);const data=fs.readFileSync(f.full);let flags=(st.mode&0o777)||0o644;let cdata=null;if(data.length>524288){try{cdata=zlib.deflateRawSync(data,{level:9});flags|=0x1000;anyGz=true;}catch(e){cdata=null;}}
items.push({rel:f.rel,full:f.full,size:data.length,csize:cdata?cdata.length:data.length,crc:pharCrc32(data),flags,time:Math.floor(st.mtimeMs/1000)||now,cdata});}
// manifiesto
const metaBuf=Buffer.from(pharSerialize(metadata),'utf8');const parts=[];
const u32=n=>{const b=Buffer.alloc(4);b.writeUInt32LE(n>>>0,0);return b;};
const head=Buffer.alloc(10);head.writeUInt32LE(items.length,0);head[4]=0x11;head[5]=0x00;head.writeUInt32LE((0x10000|(anyGz?0x1000:0))>>>0,6);
parts.push(head,u32(0),u32(metaBuf.length),metaBuf);
for(const it of items){const nb=Buffer.from(it.rel,'utf8');parts.push(u32(nb.length),nb,u32(it.size),u32(it.time),u32(it.csize),u32(it.crc),u32(it.flags),u32(0));}
const manifest=Buffer.concat(parts);
const fd=fs.openSync(outFile,'w');const h=crypto.createHash('sha1');
const w=b=>{h.update(b);let o=0;while(o<b.length)o+=fs.writeSync(fd,b,o,b.length-o);};
try{w(Buffer.from(stub,'utf8'));w(u32(manifest.length));w(manifest);
for(const it of items){if(it.cdata)w(it.cdata);else w(fs.readFileSync(it.full));it.cdata=null;}
const sig=h.digest();const tail=Buffer.concat([sig,u32(0x0002),Buffer.from('GBMB')]);let o=0;while(o<tail.length)o+=fs.writeSync(fd,tail,o,tail.length-o);}
finally{fs.closeSync(fd);}
return{count:items.length,stub};}


function pharzipParseYml(txt){const o={};let last=null;for(const raw of String(txt).replace(/\r/g,'').split('\n')){const ln=raw.replace(/\s+#.*$/,'');if(!ln.trim())continue;const m=ln.match(/^([A-Za-z0-9_-]+)\s*:\s*(.*)$/);if(m){last=m[1];o[last]=m[2].trim();continue;}const li=ln.match(/^\s+-\s*(.*)$/);if(li&&last&&(o[last]===''||Array.isArray(o[last]))){if(!Array.isArray(o[last]))o[last]=[];o[last].push(li[1].trim());}}return o;}
function pharzipPluginMeta(root){const y=pharzipParseYml(fs.readFileSync(path.join(root,'plugin.yml'),'utf8'));const unq=s=>String(s==null?'':s).trim().replace(/^["']|["']$/g,'');const lst=v=>Array.isArray(v)?v.map(unq).filter(Boolean):unq(v).replace(/[\[\]]/g,'').split(',').map(unq).filter(Boolean);return{name:unq(y.name),version:unq(y.version)||'1.0.0',main:unq(y.main),api:y.api?lst(y.api):['1.0.0'],depend:y.depend?lst(y.depend):[],description:unq(y.description),authors:y.authors?lst(y.authors):(y.author?[unq(y.author)]:[]),website:unq(y.website)};}
function pharzipPickRoot(dir){let cur=dir;for(let i=0;i<3;i++){let ents;try{ents=fs.readdirSync(cur,{withFileTypes:true}).filter(e=>e.name!=='__MACOSX'&&e.name!=='.DS_Store');}catch(e){return cur;}if(fs.existsSync(path.join(cur,'plugin.yml'))||fs.existsSync(path.join(cur,'src')))return cur;const dirs=ents.filter(e=>e.isDirectory());if(dirs.length===1&&ents.length===1){cur=path.join(cur,dirs[0].name);continue;}return cur;}return cur;}
const compilerZlib=require('zlib');
const COMPILER_DIR=path.join(DATA_DIR,'compiler'),COMPILER_TTL=20*60*1000,COMPILER_MAX=64*1024*1024,COMPILER_UNPACK_MAX=300*1024*1024;
const compilerJobs=new Map();let compilerBusy=0;
try{fs.rmSync(COMPILER_DIR,{recursive:true,force:true});fs.mkdirSync(path.join(COMPILER_DIR,'in'),{recursive:true});fs.mkdirSync(path.join(COMPILER_DIR,'out'),{recursive:true});}catch(e){}
function compilerSweep(){const now=Date.now();for(const [k,j] of compilerJobs){if(j.expires<=now){compilerJobs.delete(k);try{fs.rmSync(path.dirname(j.file),{recursive:true,force:true});}catch(e){}}}}
setInterval(compilerSweep,5*60*1000).unref();
function compilerBunzip(data){const r=spawnSync('bzip2',['-dc'],{input:data,maxBuffer:COMPILER_UNPACK_MAX});if(r.error&&r.error.code==='ENOENT')return{err:'MISSING_TOOL'};if(r.error||r.status!==0)return{err:'BAD_PHAR'};return{data:r.stdout};}
