function importIsBlockedIp(ip){if(!ip)return true;const v=net.isIP(ip);if(!v)return true;if(v===6){const l=ip.toLowerCase();const m=l.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/);if(m)return importIsBlockedIp(m[1]);return l==='::'||l==='::1'||/^f[cd]/.test(l)||/^fe[89ab]/.test(l)||/^ff/.test(l);}
const p=ip.split('.').map(Number);const[a,b]=p;return a===0||a===10||a===127||a>=224||(a===100&&b>=64&&b<=127)||(a===169&&b===254)||(a===172&&b>=16&&b<=31)||(a===192&&b===0&&p[2]===0)||(a===192&&b===168)||(a===198&&(b===18||b===19));}
// Anti-SSRF: resuelve el DNS y bloquea IPs privadas/locales
function importLookup(hostname,opts,cb){if(typeof opts==='function'){cb=opts;opts={};}dns.lookup(hostname,{all:true},(err,addrs)=>{if(err)return cb(err);const ok=(addrs||[]).filter(a=>!importIsBlockedIp(a.address));if(!ok.length||ok.length!==addrs.length){const e=new Error('BLOCKED');e.code='BLOCKED';return cb(e);}if(opts&&opts.all)return cb(null,ok.map(a=>({address:a.address,family:a.family})));cb(null,ok[0].address,ok[0].family);});}
function importNormalizeUrl(raw){let u;try{u=new URL(String(raw||'').trim());}catch(e){return null;}if(u.protocol!=='http:'&&u.protocol!=='https:')return null;if(u.username||u.password)return null;const h=u.hostname.toLowerCase();
if(h==='github.com'){const m=u.pathname.match(/^\/([^/]+)\/([^/]+)\/blob\/(.+)$/);if(m)return new URL('https://raw.githubusercontent.com/'+m[1]+'/'+m[2]+'/'+m[3]);}
if(h==='www.dropbox.com'||h==='dropbox.com'){u.searchParams.delete('dl');u.searchParams.set('dl','1');return u;}
if(h==='drive.google.com'){const m=u.pathname.match(/\/file\/d\/([^/]+)/);const id=m?m[1]:u.searchParams.get('id');if(id)return new URL('https://drive.google.com/uc?export=download&id='+encodeURIComponent(id));}
return u;}
function importSafeName(n){n=String(n||'').replace(/[\u0000-\u001f\u007f]/g,'').replace(/[\\/]+/g,'_').replace(/^\.+/,'').trim();if(n.length>120){const e=path.extname(n).slice(0,12);n=n.slice(0,120-e.length)+e;}return n;}
function importNameFromHeaders(cd,urlObj,ct){let name='';if(cd){let m=/filename\*\s*=\s*(?:UTF-8|utf-8)''([^;]+)/i.exec(cd);if(m){try{name=decodeURIComponent(m[1].trim().replace(/^"|"$/g,''));}catch(e){name=m[1];}}else{m=/filename\s*=\s*"([^"]+)"/i.exec(cd)||/filename\s*=\s*([^;]+)/i.exec(cd);if(m)name=m[1].trim();}}
if(!name){try{name=decodeURIComponent(path.basename(urlObj.pathname));}catch(e){name=path.basename(urlObj.pathname);}}
name=importSafeName(name);if(!name)name='archivo_'+Date.now();
if(!path.extname(name)){const t=String(ct||'').split(';')[0].trim().toLowerCase();const map={'application/zip':'.zip','application/x-zip-compressed':'.zip','application/java-archive':'.jar','application/x-gzip':'.gz','application/gzip':'.gz','application/x-tar':'.tar','application/x-rar-compressed':'.rar','application/vnd.rar':'.rar','application/x-7z-compressed':'.7z','application/json':'.json','text/plain':'.txt','text/yaml':'.yml','application/x-yaml':'.yml'};if(map[t])name+=map[t];}
return name;}
function importUniqueName(dir,name){if(!fs.existsSync(path.join(dir,name)))return name;const ext=path.extname(name),stem=name.slice(0,name.length-ext.length);for(let i=1;i<1000;i++){const c=stem+' ('+i+')'+ext;if(!fs.existsSync(path.join(dir,c)))return c;}return stem+'_'+Date.now()+ext;}
// MediaFire: la página trae el link directo; se lee y se descarga ese
function importIsMediafire(u){const h=u.hostname.toLowerCase();return(h==='mediafire.com'||h.endsWith('.mediafire.com'))&&/^\/(file|file_premium|view|download)\//.test(u.pathname);}
function importMediafireParse(html){if(typeof html!=='string')return null;const dec=x=>x.replace(/&amp;/g,'&').replace(/&#0?38;/g,'&');
let m=/data-scrambled-url\s*=\s*["']([A-Za-z0-9+\/=_-]+)["']/i.exec(html);if(m){try{const d=Buffer.from(m[1].replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8').trim();if(/^https?:\/\//i.test(d))return dec(d);}catch(e){}}
m=/id\s*=\s*["']downloadButton["'][^>]*?href\s*=\s*["'](https?:\/\/[^"']+)["']/i.exec(html)||/href\s*=\s*["'](https?:\/\/[^"']+)["'][^>]*?id\s*=\s*["']downloadButton["']/i.exec(html);if(m)return dec(m[1]);
m=/https?:\/\/download[0-9a-z-]*\.mediafire\.com\/[^"'\s<>\\]+/i.exec(html);return m?dec(m[0]):null;}
function importFetchText(u,cb,hops){hops=hops||0;const hn=u.hostname.replace(/^\[|\]$/g,'');if(net.isIP(hn)&&importIsBlockedIp(hn))return cb('BLOCKED');const lib=u.protocol==='https:'?https:http;let done=false;const fin=(e,t)=>{if(!done){done=true;cb(e,t);}};
const req=lib.request(u,{method:'GET',lookup:importLookup,timeout:20000,headers:{'User-Agent':IMPORT_UA,'Accept':'text/html,application/xhtml+xml','Accept-Language':'en-US,en;q=0.9'}},resp=>{const sc=resp.statusCode||0;
if(sc>=300&&sc<400&&resp.headers.location){resp.resume();if(hops>=3)return fin('REDIRECTS');let nu;try{nu=new URL(resp.headers.location,u);}catch(e){return fin('BAD_URL');}if(nu.protocol!=='https:'&&nu.protocol!=='http:')return fin('BAD_URL');return importFetchText(nu,(e,t)=>fin(e,t),hops+1);}
if(sc<200||sc>=300){resp.resume();return fin('HTTP');}
const chunks=[];let n=0;resp.on('data',c=>{n+=c.length;if(n>2*1024*1024){try{resp.destroy();}catch(e){}return fin('FAILED');}chunks.push(c);});resp.on('end',()=>fin(null,Buffer.concat(chunks).toString('utf8')));resp.on('error',()=>fin('FAILED'));});
req.on('timeout',()=>req.destroy(Object.assign(new Error('timeout'),{code:'ETIMEDOUT'})));req.on('error',e=>fin(e&&e.code==='BLOCKED'?'BLOCKED':(e&&e.code==='ETIMEDOUT')?'TIMEOUT':'FAILED'));req.end();}
function importResolveMediafire(u,cb){importFetchText(u,(err,html)=>{if(err)return cb(err);const d=importMediafireParse(html);if(!d)return cb('MEDIAFIRE');let du;try{du=new URL(d);}catch(e){return cb('MEDIAFIRE');}const hn=du.hostname.toLowerCase();if(du.protocol!=='https:'&&du.protocol!=='http:')return cb('MEDIAFIRE');if(!(hn==='mediafire.com'||hn.endsWith('.mediafire.com')))return cb('MEDIAFIRE');cb(null,du);});}
function importFail(job,code,extra){if(job.state==='done'||job.state==='error')return;job.state='error';job.code=code;job.extra=extra||null;job.finishedAt=Date.now();if(job.tmp){try{fs.unlinkSync(job.tmp);}catch(e){}}}
function importRun(job,urlObj){const dir=path.join(SERVERS_PATH,job.serverId,'importaciones');
try{const base=path.join(SERVERS_PATH,job.serverId);safeJoin(base,'importaciones');fs.mkdirSync(dir,{recursive:true});safeJoin(base,'importaciones');}catch(e){return importFail(job,'FAILED');}
let hops=0;
const hardTimer=setTimeout(()=>{try{job.req&&job.req.destroy();}catch(e){}importFail(job,'TIMEOUT');},15*60*1000);
const finish=()=>clearTimeout(hardTimer);
const go=u=>{const _hn=u.hostname.replace(/^\[|\]$/g,'');if(net.isIP(_hn)&&importIsBlockedIp(_hn)){finish();return importFail(job,'BLOCKED');}const lib=u.protocol==='https:'?https:http;let settled=false;
const req=lib.request(u,{method:'GET',lookup:importLookup,timeout:30000,headers:Object.assign({'User-Agent':IMPORT_UA,'Accept':'*/*'},/(^|\.)mediafire\.com$/i.test(u.hostname)?{'Referer':'https://www.mediafire.com/'}:{})},resp=>{
const sc=resp.statusCode||0;
if(sc>=300&&sc<400&&resp.headers.location){resp.resume();if(++hops>5){finish();return importFail(job,'REDIRECTS');}let nu;try{nu=new URL(resp.headers.location,u);}catch(e){finish();return importFail(job,'BAD_URL');}if(nu.protocol!=='http:'&&nu.protocol!=='https:'){finish();return importFail(job,'BAD_URL');}return go(nu);}
if(sc<200||sc>=300){resp.resume();finish();return importFail(job,'HTTP',{status:sc});}
const ct=String(resp.headers['content-type']||'').toLowerCase();const cd=resp.headers['content-disposition']||'';
if(ct.startsWith('text/html')&&!/attachment/i.test(cd)){resp.resume();finish();return importFail(job,'NOT_FILE');}
const total=parseInt(resp.headers['content-length'],10)||0;job.total=total;
if(total>IMPORT_MAX_BYTES){resp.resume();finish();return importFail(job,'TOO_BIG');}
const rec=getServersDb()[job.serverId];const lim=rec&&typeof rec.diskLimit==='number'?rec.diskLimit:0;
const proceed=()=>{if(job.state==='error')return;job.name=importNameFromHeaders(cd,u,ct);job.tmp=path.join(dir,'.imp_'+crypto.randomBytes(6).toString('hex')+'.part');
const ws=fs.createWriteStream(job.tmp,{mode:0o644});job.state='downloading';let received=0,aborted=false;
const abort=code=>{if(aborted)return;aborted=true;try{resp.destroy();}catch(e){}try{ws.destroy();}catch(e){}finish();importFail(job,code);};
resp.on('data',ch=>{received+=ch.length;job.received=received;if(received>IMPORT_MAX_BYTES)abort('TOO_BIG');});
resp.on('error',()=>abort('FAILED'));resp.on('aborted',()=>abort('FAILED'));
ws.on('error',()=>abort('FAILED'));
ws.on('finish',()=>{if(aborted||job.state==='error')return;try{if(total&&received<total)return abort('FAILED');const final=importUniqueName(dir,job.name);fs.renameSync(job.tmp,path.join(dir,final));job.tmp=null;job.name=final;job.state='done';job.finishedAt=Date.now();finish();
try{logActivity(job.userId,job.username,'file_import','Importó un archivo desde un link',job.serverId,{file:'importaciones/'+final,value:u.hostname});}catch(_e){}}catch(e){abort('FAILED');}});
resp.pipe(ws);};
if(lim>0){getServerDiskMb(job.serverId,true).then(used=>{if(used+(total||0)/1048576>=lim){resp.resume();finish();return importFail(job,'DISK_FULL');}proceed();}).catch(()=>proceed());}else proceed();
});
job.req=req;
req.on('timeout',()=>{req.destroy(Object.assign(new Error('timeout'),{code:'ETIMEDOUT'}));});
req.on('error',e=>{if(settled)return;settled=true;finish();importFail(job,e&&e.code==='BLOCKED'?'BLOCKED':(e&&e.code==='ETIMEDOUT')?'TIMEOUT':'FAILED');});
req.end();};
if(importIsMediafire(urlObj)){importResolveMediafire(urlObj,(err,direct)=>{if(job.state==='error')return;if(err){finish();return importFail(job,err==='HTTP'?'MEDIAFIRE':err);}go(direct);});}else go(urlObj);}
app.post('/api/servers/:id/import',requireAuth,guard('files'),diskGuard,(req,res)=>{const id=req.params.id;const raw=(req.body&&req.body.url)||'';if(typeof raw!=='string'||raw.length>2048)return res.status(400).json({success:false,code:'BAD_URL',error:'Link inválido'});const u=importNormalizeUrl(raw);if(!u)return res.status(400).json({success:false,code:'BAD_URL',error:'Link inválido'});
let perServer=0,perUser=0;for(const j of importJobs.values()){if(j.state==='error'||j.state==='done')continue;if(j.serverId===id)perServer++;if(j.userId===req.currentUser.id)perUser++;}
if(perServer>=2||perUser>=3)return res.status(429).json({success:false,code:'BUSY',error:'Hay demasiadas importaciones en curso'});
const job={id:crypto.randomBytes(8).toString('hex'),serverId:id,userId:req.currentUser.id,username:req.currentUser.username,state:'connecting',received:0,total:0,name:'',code:null,extra:null,startedAt:Date.now(),finishedAt:0,req:null,tmp:null};importJobs.set(job.id,job);importRun(job,u);res.json({success:true,job:job.id});});
app.get('/api/servers/:id/import/:job',requireAuth,guard('files'),(req,res)=>{const j=importJobs.get(req.params.job);if(!j||j.serverId!==req.params.id||(j.userId!==req.currentUser.id&&!isAdmin(req.currentUser)))return res.status(404).json({success:false,code:'NOT_FOUND',error:'Importación no encontrada'});res.json({success:true,state:j.state,received:j.received,total:j.total,name:j.name,code:j.code,extra:j.extra});});

app.get('/api/servers/:id/backups',requireAuth,guard('backups'),(req,res)=>{const files=fs.existsSync(BACKUPS_PATH)?fs.readdirSync(BACKUPS_PATH).filter(f=>f.startsWith(req.params.id+'_')):[];res.json({success:true,backups:files.map(f=>({name:f,size:fs.statSync(path.join(BACKUPS_PATH,f)).size}))});});
app.post('/api/servers/:id/backup',requireAuth,guard('backups'),async(req,res)=>{const id=req.params.id;const server=getServersDb()[id];if(!server)return res.status(404).json({success:false,error:'Servidor no encontrado'});const owner=getUsers().find(u=>u.id===server.ownerId);const backupLimit=owner?.backupLimit??5;if(backupLimit>=0){const existingBackups=fs.existsSync(BACKUPS_PATH)?fs.readdirSync(BACKUPS_PATH).filter(f=>f.startsWith(id+'_')):[];if(existingBackups.length>=backupLimit){return res.status(400).json({success:false,error:'Límite de backups alcanzado ('+backupLimit+')'});}}const timestamp=new Date().toISOString().replace(/[:.]/g,'-');const filename=id+'_'+timestamp+'.tar.gz';execFile('tar',['-czf',path.join(BACKUPS_PATH,filename),'-C',SERVERS_PATH,'--exclude=PocketMine-MP.phar','--exclude=server.jar',id],{timeout:120000},(err)=>{if(err){return res.status(500).json({success:false,error:'No se pudo crear el backup'});}res.json({success:true,file:filename});});});
function backupFileOk(id,name){return typeof name==='string'&&name.startsWith(id+'_')&&/^[A-Za-z0-9._-]+\.tar\.gz$/.test(name)&&!name.includes('..');}
app.get('/api/servers/:id/backups/:file/download',requireAuth,downloadLimiter,guard('backups'),(req,res)=>{if(!backupFileOk(req.params.id,req.params.file))return res.status(400).json({success:false,error:'Ruta inválida'});const file=path.join(BACKUPS_PATH,req.params.file);if(!file.startsWith(path.resolve(BACKUPS_PATH)))return res.status(400).json({success:false,error:'Ruta inválida'});if(!fs.existsSync(file))return res.status(404).json({success:false,error:'Backup no encontrado'});res.download(file);});
const restoringSet=new Set();
app.post('/api/servers/:id/backups/:file/restore',requireAuth,guard('backups'),async(req,res)=>{const id=req.params.id,name=req.params.file;if(!backupFileOk(id,name))return res.status(400).json({success:false,code:'BAD_FILE',error:'Backup inválido'});const bk=path.join(BACKUPS_PATH,name);if(!bk.startsWith(path.resolve(BACKUPS_PATH))||!fs.existsSync(bk))return res.status(404).json({success:false,code:'NOT_FOUND',error:'Backup no encontrado'});
if(restoringSet.has(id))return res.status(409).json({success:false,code:'BUSY',error:'Ya se está restaurando un backup'});restoringSet.add(id);const truncate=!!(req.body&&req.body.truncate);const base=path.join(SERVERS_PATH,id);let tmp=null;
try{if(running.has(id)||starting.has(id)){await stopProcessAsync(id,5000,9000);}
tmp=path.join(base,'.restore_'+crypto.randomBytes(6).toString('hex'));fs.mkdirSync(tmp,{recursive:true});
const r=await runTool('tar',['-xzf',bk,'-C',tmp,'--no-same-owner']);if(!r.ok){if(r.missing)return res.status(500).json({success:false,code:'MISSING_TOOL',tool:'tar',error:'Falta la herramienta tar'});return res.status(500).json({success:false,code:'BAD_ARCHIVE',error:'No se pudo leer el backup: '+(r.err||'dañado')});}
stripSymlinks(tmp);const src=path.join(tmp,id);if(!fs.existsSync(src)||!fs.statSync(src).isDirectory())return res.status(500).json({success:false,code:'BAD_ARCHIVE',error:'El backup no tiene el formato esperado'});
if(truncate){const keep=new Set([path.basename(tmp),'PocketMine-MP.phar','server.jar']);for(const n of fs.readdirSync(base)){if(keep.has(n))continue;try{fs.rmSync(path.join(base,n),{recursive:true,force:true});}catch(e){}}}
copyTreeSafe(src,base,base);
try{logActivity(req.currentUser.id,req.currentUser.username,'backup_restore','Restauró un backup',id,{file:name,value:truncate?'truncate':''});}catch(_e){}
res.json({success:true});}
catch(e){res.status(500).json({success:false,code:'FAILED',error:'No se pudo restaurar el backup'});}
finally{restoringSet.delete(id);if(tmp){try{fs.rmSync(tmp,{recursive:true,force:true});}catch(_e){}}}});
